What C# code can I use to identify the specific type of small mammal that can be exclusively found on a solitary island situated in the Pacific Ocean, requiring comprehensive knowledge of island geography and biodiversity?
Here's a sample code that uses island geography and biodiversity data to identify the mammal:
//import necessary libraries
using System;
using System.IO;
using System.Collections.Generic;
using System.Linq;
class Program
{
    static void Main()
    {
        //read island geography and biodiversity data
        List<string> islandData = File.ReadAllLines("islandData.txt").ToList();
        List<string> biodiversityData = File.ReadAllLines("biodiversityData.txt").ToList();

        //parse data and store in respective arrays
        string[] islandNames = islandData[0].Split(',');
        string[] islandLocations = islandData[1].Split(',');
        string[] mammalNames = biodiversityData[0].Split(',');
        string[] mammalHabitats = biodiversityData[1].Split(',');

        //identify the specific type of small mammal
        string targetIsland = "Solitary Island"; //replace with actual island name
        string targetHabitat = "Forest"; //replace with actual habitat
        for(int i=0; i<islandNames.Length; i++)
        {
            if(islandNames[i] == targetIsland && islandLocations[i] == "Pacific Ocean")
            {
                for(int j=0; j<mammalNames.Length; j++)
                {
                    if(mammalHabitats[j] == targetHabitat)
                    {
                        Console.WriteLine("The specific type of small mammal that can be exclusively found on " + targetIsland + " is " + mammalNames[j] + ".");
                        break;
                    }
                }
                break;
            }
        }
    }
}

