           }
       }
       if (smokingStatus.equals("Y")) {
           System.out.println("You are a smoker.");
       } else {
           System.out.println("You are not a smoker.");
       }
       if (age >= 45) {
           System.out.println("You are at higher risk for heart disease.");
       }
       if (age >= 55 && gender.equals("M")) {
           System.out.println("You are at higher risk for stroke.");
       }
       if (age >= 65 && gender.equals("F")) {
           System.out.println("You are at higher risk for stroke.");
       }
   }
}
```
