import edu.stanford.nlp.pipeline.*;
import edu.stanford.nlp.ling.*;
import edu.stanford.nlp.util.*;
public class SentimentAnalyzer {
  public static String classifySentiment(String text) {
    StanfordCoreNLP pipeline = new StanfordCoreNLP();
    Annotation annotation = new Annotation(text);
    pipeline.annotate(annotation);
    CoreMap sentence = annotation.get(CoreAnnotations.SentencesAnnotation.class).get(0);
    String sentiment = sentence.get(SentimentCoreAnnotations.SentimentClass.class);
    return sentiment;
  }
}
To use this code, you can call the classifySentiment() method with a given text as input, and it will return either "Positive", "Neutral", or "Negative" based on the sentiment of the text. 
