% Get the Part-Of-Speech (POS) tags for each token in the sentence
tokens = annotation.get(CoreAnnotations.TokensAnnotation.class);
posTags = cell(tokens.size(), 1);
for i = 1:length(posTags)
    posTags{i} = tokens.get(i-1).get(CoreAnnotations.PartOfSpeechAnnotation.class);
end
% Identify the tense of the sentence based on the POS tags
if strcmp(posTags{1}, 'MD') && strcmp(posTags{2}, 'VB') && strcmp(posTags{3}, 'TO') && strcmp(posTags{4}, 'VB') && strcmp(posTags{5}, 'DT') && strcmp(posTags{6}, 'NN') && strcmp(posTags{7}, 'NN')
    tense = 'present conditional';
else
    tense = 'unknown';
end
disp(['The tense of the sentence "', sentence, '" is ', tense]);
