Sure, here's a JavaScript code algorithm that can calculate the distance between the user's location and the closest Italian restaurant:
```javascript
// Define the user's location coordinates
const userLat = 40.7128;
const userLng = -74.0060;
// Create an array of Italian restaurants with their location and cuisine type
const italianRestaurants = [
  { name: "Pasta Palace", lat: 40.7123, lng: -74.0081, cuisine: "Italian" },
  { name: "Pizza Place", lat: 40.7129, lng: -74.0055, cuisine: "Italian" },
  { name: "Mama Mia's", lat: 40.7136, lng: -74.0093, cuisine: "Italian" },
  { name: "Ristorante Italiano", lat: 40.7118, lng: -74.0064, cuisine: "Italian" },
  { name: "Trattoria Toscana", lat: 40.7121, lng: -74.0077, cuisine: "Italian" }
];
// Define a function to calculate the distance between two points using the Haversine formula
function getDistance(lat1, lng1, lat2, lng2) {
  const R = 6371; // Earth's radius in km
  const dLat = (lat2 - lat1) * Math.PI / 180;
  const dLng = (lng2 - lng1) * Math.PI / 180;
  const a =
    Math.sin(dLat / 2) * Math.sin(dLat / 2) +
    Math.cos(lat1 * Math.PI / 180) * Math.cos(lat2 * Math.PI / 180) *
    Math.sin(dLng / 2) * Math.sin(dLng / 2);
  const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
  const d = R * c; // Distance in km
  return d;
}
// Define a function to find the closest Italian restaurant to the user's location
function getClosestItalianRestaurant(userLat, userLng, italianRestaurants) {
  let closestRestaurant = null;
  let closestDistance = Infinity;
  for (let i = 0; i < italianRestaurants.length; i++) {
    const restaurant = italianRestaurants[i];
    const distance = getDistance(userLat, userLng, restaurant.lat, restaurant.lng);
    if (distance < closestDistance && restaurant.cuisine === "Italian") {
      closestDistance = distance;
      closestRestaurant = restaurant;
    }
  }
  return closestRestaurant;
}
// Call the function to get the closest Italian restaurant to the user's location
const closestItalianRestaurant = getClosestItalianRestaurant(userLat, userLng, italianRestaurants);
// Print the result
console.log("The closest Italian restaurant is " + closestItalianRestaurant.name + " and it is " + closestDistance.toFixed(2) + " km away.");
```
The algorithm uses the Haversine formula to calculate the distance between the user's location and each Italian restaurant in the array. It then compares the distances to find the closest Italian restaurant and returns its name, location, and cuisine type. The code is optimized for efficiency by using a for loop to iterate through the array of restaurants and a conditional statement to only consider Italian restaurants.

