        let propsUsed = propsTableView.indexPathsForSelectedRows?.map { props[$0.row] }
        let costumesUsed = costumesTableView.indexPathsForSelectedRows?.map { costumes[$0.row] }
        // Determine the validity of the ghost's claims based on the success of the play
        let success = propsUsed?.contains("Poison") ?? false && costumesUsed?.contains("King") ?? false
