// Define a recursive function to compute the maximum value across all files and all columns
def computeMaxValueRec(fileNames: Seq[String]): Int = {
  if (fileNames.isEmpty) {
    // Base case: no files to process
    0
  } else if (fileNames.length == 1) {
    // Base case: only one file to process
    val file = Source.fromFile(fileNames.head)
    val data = file.getLines.map(_.trim.toInt).toSeq
    file.close()
    computeMaxValue(data)
  } else {
    // Recursive case: split the files into two halves and compute the maximum value for each half
    val (leftFiles, rightFiles) = fileNames.splitAt(fileNames.length / 2)
    val leftMaxVal = computeMaxValueRec(leftFiles)
    val rightMaxVal = computeMaxValueRec(rightFiles)
