Here's an example JSON format:
{
  "products": [
    {
      "name": "Product A",
      "price": 50,
      "discount": 0.1
    },
    {
      "name": "Product B",
      "price": 100,
      "discount": 0.2
    },
    {
      "name": "Product C",
      "price": 75,
      "discount": 0.15
    }
  ]
}
// Read the input file and create a list of products
def read_products(file):
    with open(file) as f:
        data = json.load(f)
    return data["products"]
// Calculate the final price after applying the discounts
def calculate_final_price(products):
    for product in products:
        price = product["price"]
        discount = product["discount"]
        final_price = price * (1 - discount)
        product["final_price"] = final_price
// Sort the products by final price in descending order
def sort_products_by_price(products):
    return sorted(products, key=lambda x: x["final_price"], reverse=True)
// Write the sorted products to a new JSON file
def write_products(products, file):
    data = {"products": products}
    with open(file, "w") as f:
        json.dump(data, f, indent=4)
input_file = "products.json"
output_file = "sorted_products.json"
products = read_products(input_file)
calculate_final_price(products)
sorted_products = sort_products_by_price(products)
write_products(sorted_products, output_file)
