package main
import (
    "encoding/xml"
    "fmt"
)
type Sentence struct {
    Subject string `xml:"subject"`
    Verb    string `xml:"verb"`
    Object  string `xml:"object"`
}
func main() {
    // Create two separate sentences
    sentence1 := Sentence{Subject: "He", Verb: "was", Object: "late"}
    sentence2 := Sentence{Subject: "He", Verb: "missed", Object: "the meeting"}
    // Combine the two sentences into a compound sentence using XML syntax
    compoundSentence := fmt.Sprintf("<sentence>%s %s and %s %s</sentence>", sentence1.Subject, sentence1.Verb, sentence2.Subject, sentence2.Object)
    // Parse the XML to extract the sentence
    var parsedSentence Sentence
    err := xml.Unmarshal([]byte(compoundSentence), &parsedSentence)
    if err != nil {
        fmt.Println("Error parsing XML:", err)
    }
    // Print the final compound sentence
    fmt.Println(parsedSentence.Subject, parsedSentence.Verb, parsedSentence.Object)
}
