package main
import (
	"fmt"
	"strings"
)
func cleanSentence(sentence string) string {
	words := strings.Fields(sentence)
	uniqueWords := make(map[string]bool)
	cleanedSentence := ""
	for i, word := range words {
		if !uniqueWords[word] {
			uniqueWords[word] = true
			if i != 0 {
				cleanedSentence += " "
			}
			cleanedSentence += word
		}
	}
	return cleanedSentence
}
func main() {
	originalSentence := "We have done have had it done already"
	cleanedSentence := cleanSentence(originalSentence)
	fmt.Println(cleanedSentence)
	// Output: "We have done had it already"
}
```

