  int a[m][n], b[m][n], sum[m][n];
  cout << "Enter elements of matrix a:" << endl;
  for(int i = 0; i < m; i++) {
    for(int j = 0; j < n; j++) {
      cin >> a[i][j];
    }
  }
  cout << "Enter elements of matrix b:" << endl;
  for(int i = 0; i < m; i++) {
    for(int j = 0; j < n; j++) {
      cin >> b[i][j];
    }
  }
  for(int i = 0; i < m; i++) {
    for(int j = 0; j < n; j++) {
      sum[i][j] = a[i][j] + b[i][j];
    }
  }
  cout << "Sum of matrices:" << endl;
  for(int i = 0; i < m; i++) {
    for(int j = 0; j < n; j++) {
      cout << sum[i][j] << " ";
    }
    cout << endl;
  }
  return 0;
} 
