How can I use C# code to generate a list of the five most used keywords in an article titled "Advantages of Technology in Business" using Markdown?
Here is a sample code snippet that can achieve this:
string article = "# Advantages of Technology in Business \n" +
                  "Technology has brought about many benefits to the business world. With the advancement of technology, businesses can now communicate with customers more easily and efficiently. Here are some of the main advantages: \n" +
                  "- Increased productivity \n" +
                  "- Improved communication \n" +
                  "- Better decision-making \n" +
                  "- Increased efficiency \n" +
                  "- Cost savings \n";
var keywordFrequency = new Dictionary<string, int>();
var words = Regex.Matches(article, @"\b[\w']*\b")
                .Cast<Match>()
                .Select(match => match.Value.ToLower())
                .ToList();
foreach (var word in words)
{
    if (!keywordFrequency.ContainsKey(word))
    {
        keywordFrequency[word] = 0;
    }
    keywordFrequency[word]++;
}
var topFiveKeywords = keywordFrequency.OrderByDescending(x => x.Value)
                                     .Take(5)
                                     .Select(x => x.Key);
Console.WriteLine("The top five keywords in the article are:");
foreach (var keyword in topFiveKeywords)
{
    Console.WriteLine("- " + keyword);
}

